	// 扎营时原版锁定 ×1 / ×2 按钮、按扎营速度走；这里直接设成玩家选的速度
	q.quicker_setCampTime <- function( _mult, _button )
	{
		if (this.m.MenuStack.hasBacksteps() || ::World.Assets == null || !::World.Assets.isCamping() || ::Quicker.isEscorting(this))
			return false;
		this.m.LastWorldSpeedMult = _mult;
		this.setPause(false);
		::World.setSpeedMult(_mult);
		if ("TopbarDayTimeModule" in ::World && ::World.TopbarDayTimeModule != null)
			::World.TopbarDayTimeModule.updateTimeButtons(_button);
		::logDebug("Quicker Mod | Camp Speed set to x" + _mult);
		return true;
	}

	q.setNormalTime = @(__original) function( ... )
	{
		if (this.quicker_setCampTime(::Const.World.SpeedSettings.NormalMult, 1))
			return;
		::Quicker.applySpecialSpeedMults(this);
		vargv.insert(0, this);
		return __original.acall(vargv);
	}

